import {createClient} from "@/lib/supabase/server";export default async function Vendor(){const s=await createClient();const{data:{user}}=await s.auth.getUser();if(!user)return <main className="shell"><h1>Vendor portal</h1><p>Please sign in.</p></main>;const{data:v}=await s.from("vendor_profiles").select("*").eq("user_id",user.id).maybeSingle();const{data:orders}=await s.from("orders").select("*").eq("vendor_user_id",user.id).neq("status","delivered");return <main className="shell"><h1>Vendor portal</h1><section className="card"><b>{v?.business_name||"Vendor application required"}</b><p>{v?.is_available?"Online":"Offline"} · {v?.status||"not registered"}</p></section>{orders?.map(o=><section className="card" key={o.id}><b>{o.order_code}</b><p>{o.quantity_kg} kg · {o.status}</p></section>)}</main>}